from dataclasses import dataclass, replace
from typing import NamedTuple
class Node(NamedTuple):                       # tuple = deeply immutable, hashable
    text: str
    kids: tuple["Node", ...] = ()
@dataclass(frozen=True)
class Loc:
    focus: Node
    path: tuple[tuple[Node, int], ...] = ()   # (parent, child index) per level
def up(loc: Loc) -> Loc:                      # rebuild the parent, O(children)
    parent, i = loc.path[-1]
    return Loc(replace(parent, kids=parent.kids[:i] + (loc.focus,) + parent.kids[i + 1:]), loc.path[:-1])
